class Gradebook:
    def __init__(self) -> None:
        self.assignments = []  # list of (name, weight, kind)
        self.grades = {}  # student -> {assignment: grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments.append((name, weight, kind))

    def record(self, student: str, assignment: str, grade: float) -> None:
        """Record a grade for a student on a specific assignment."""
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        """Calculate the weighted average for a student."""
        if student not in self.grades:
            # If student has no grades recorded, use default grade 2.0 for all assignments
            total_weighted_sum = 0.0
            total_weight = 0.0
            for name, weight, kind in self.assignments:
                total_weighted_sum += 2.0 * weight
                total_weight += weight
            if total_weight == 0:
                return 2.0
            result = total_weighted_sum / total_weight
            return round(result, 2)

        # Get all quiz grades for this student
        quiz_grades = []
        homework_grades = []

        # Collect grades for each assignment
        for name, weight, kind in self.assignments:
            if name in self.grades[student]:
                grade = self.grades[student][name]
                if kind == "quiz":
                    quiz_grades.append((grade, weight))
                else:  # homework
                    homework_grades.append((grade, weight))
            else:
                # Assignment not recorded, use default grade 2.0
                if kind == "quiz":
                    quiz_grades.append((2.0, weight))
                else:  # homework
                    homework_grades.append((2.0, weight))

        # Handle quiz dropping: if more than one quiz, drop the lowest grade
        if len(quiz_grades) > 1:
            # Sort by grade (ascending) and remove the lowest
            quiz_grades.sort(key=lambda x: x[0])
            quiz_grades = quiz_grades[1:]  # drop the lowest

        # Calculate weighted sum and total weight
        weighted_sum = 0.0
        total_weight = 0.0

        # Add homework grades
        for grade, weight in homework_grades:
            weighted_sum += grade * weight
            total_weight += weight

        # Add quiz grades (after dropping lowest if applicable)
        for grade, weight in quiz_grades:
            weighted_sum += grade * weight
            total_weight += weight

        # Handle case where there are no assignments
        if total_weight == 0:
            return 2.0

        result = weighted_sum / total_weight
        return round(result, 2)
